const result = {};
result["Topic"] = $('Wait To Update New Topic').first().json.fields.Topic;
for (const item of $input.first().json.records) {
  if(item.fields.Key=== "Website" || item.fields.Key === "Sitemap Xml"){
      result[item.fields.Key] = item.fields.Value.replace("http://", "").replace("https://", "");
  } else {
  result[item.fields.Key] = item.fields.Value;
  }
}

return result;

const chapters = []

for (const item of $input.all()) {
  for (const record of item.json.records) {
    if(record.fields['Select And Process Chapters'] && record.fields['Select And Process Chapters'][0]){
    let subchapters = record.fields['Subchapters'].split(',');
    let chapter = { "chapter_title": record.fields['Chapter Title'], "subchapters": subchapters }  
    chapters.push(chapter);
    }
  }
}

return {chapters: chapters}

