const chapters = []

for (const item of $input.all()) {
  for (const contentId of $('Airtable Select Content2').first().json.fields['Chapter Content'] ) {  
    for (const record of item.json.records) {     
      if(contentId == record.id){
        const item = {"Chapter Id":contentId,
                      "Chapter Title":record.fields['Chapter Title'], 
                      "Content Body": record.fields['Chapter Content'],
                     "Subchapters": record.fields['Subchapters'] };
        chapters.push(item);
      }
    }
  }
}

return {chapters: chapters}

let article = "";

// Deeper Research Format
if($('Settings2').first().json['Deeper Research'].toLowerCase() === "yes"){
  article += "## " + $('Blog Planner').first().json.output.introduction_title + "\n" 
}

// Introduction
article += $('Blog Planner').first().json.output.introduction;
article += "\n\n";

var i = 0;
for (const item of $input.all()) {
  // Add the chapter title as a Markdown level 2 header
  article += "## " + $('New Chapters').first().json.chapters[i]['Chapter Title'] + "\n";

  // Insert the chapter image if it exists (using Markdown image syntax)
  if (item.json.fields['Original Image Url']) {
    article += `![${item.json.fields['Chapter Title']}](${item.json.fields['Original Image Url']})\n\n`;
  }
  // Add the chapter content
  article += $('New Chapters').first().json.chapters[i]['Content Body'];
  article += "\n\n";

  i++;
}

// Conclusion
article += "## " + $('Blog Planner').first().json.output.conclusion_title + "\n\n";
article += $('Blog Planner').first().json.output.conclusion;
article += "\n\n";

