                      "Generate Image": imageRecord.fields['Generate Image'],
                      "Manual Image": imageRecord.fields['Manual Image'],
                      "Status": imageRecord.fields['Status'],
                      "Execute Flow": imageRecord.fields['Execute Flow'],
                     };
        chapters.push(item);
      }
    }
  }
}

return {chapters: chapters}

